module fractional_n_pll (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] input_freq,  // Input frequency  
    input wire [7:0] fractional_multiplier, // Fractional multiplier  
    output reg [15:0] output_freq // Output frequency  
);  

    reg [15:0] phase_accumulator;  
    reg [15:0] fractional_part;  
    wire [15:0] freq_command;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase_accumulator <= 16'd0;  
            output_freq <= 16'd0;  
        end else begin  
            // Update phase accumulator  
            phase_accumulator <= phase_accumulator + input_freq * fractional_multiplier;  
            fractional_part <= phase_accumulator[15:8];  
            output_freq <= fractional_part;  
        end  
    end  
endmodule

