module array_multiplier (  
    input [3:0] A,  
    input [3:0] B,  
    output [7:0] P  
);  
    wire [3:0] partial[3:0];  
    assign partial[0] = A & {4{B[0]}};  
    assign partial[1] = A & {4{B[1]}} << 1;  
    assign partial[2] = A & {4{B[2]}} << 2;  
