module VCO (
    input wire clk,
    input wire reset,
    input wire [2:0] control,
    output reg out
);
    reg [25:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter >= (1 << (control + 20))) begin // Adjust frequency based on control input
                out <= ~out; // Toggle output
                counter <= 0; // Reset counter
            end
        end
    end
endmodule

