module pll(clk_in, reset, clk_out);  
    input clk_in;  
    input reset;  
    output reg clk_out;  

    reg [3:0] phase_detector;  
    reg [3:0] low_pass_filter;  
    reg [3:0] vco;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            phase_detector <= 0;  
            low_pass_filter <= 0;  
            vco <= 0;  
            clk_out <= 0;  
        end else begin  
            // Phase Detector Logic  
            phase_detector <= phase_detector + 1;  
            // Low Pass Filter Logic  
            low_pass_filter <= (phase_detector > 4'b1000) ? phase_detector : low_pass_filter;  
            // VCO Logic  
            vco <= low_pass_filter;  
            // Output Clock Generation  
            clk_out <= (vco > 4'b0100);  
        end  
    end  
endmodule

