module shift_register (  
    input clk,  
    input reset,  
    input serial_in,  
    output reg [15:0] shift_out  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            shift_out <= 16'b0;  
        else  
            shift_out <= {shift_out[14:0], serial_in};  
    end  
endmodule

