module pll #(parameter MULTIPLIER = 2) (
    input wire clk_in,
    input wire reset,
    output reg clk_out
);
    reg [1:0] state; // 0: unlocked, 1: locked
    reg [3:0] counter;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            state <= 0;
            counter <= 0;
            clk_out <= 0;
        end else begin
            if (state == 0) begin
                // Searching for lock
                counter <= counter + 1;
                if (counter >= MULTIPLIER - 1) begin
                    state <= 1;
                    counter <= 0;
                end
            end else begin
                // Locked state
                clk_out <= ~clk_out;
                counter <= counter + 1;
                if (counter >= MULTIPLIER - 1) begin
                    counter <= 0;
                end
            end
        end
    end
endmodule

