module ethernet_mac_controller(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] frame_data,  
    input wire frame_valid,  
    output reg valid_signal  
);  

    reg [7:0] frame_buffer [0:15];  
    reg [3:0] frame_length;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            frame_length <= 0;  
            valid_signal <= 0;  
        end else if (frame_valid) begin  
            if (frame_length < 16) begin  
                frame_buffer[frame_length] <= frame_data;  
                frame_length <= frame_length + 1;  
            end else begin  
                valid_signal <= 0;  
            end  
        end  
        valid_signal <= (frame_length > 0 && frame_length <= 16);  
    end  
endmodule

