module fifo_queue (
    input wire clk,
    input wire rst,
    input wire enqueue,
    input wire dequeue,
    input wire [7:0] data_in,
    output reg [7:0] data_out,
    output reg empty,
    output reg full
);
    reg [7:0] fifo [3:0]; // FIFO array of depth 4
    reg [1:0] head, tail;
    reg [2:0] count; // to track the number of elements in the FIFO

    initial begin
        head = 0;
        tail = 0;
        count = 0;
        empty = 1;
        full = 0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            head <= 0;
            tail <= 0;
            count <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            // Enqueue operation
            if (enqueue && !full) begin
                fifo[tail] <= data_in;
                tail <= (tail + 1) % 4;
                count <= count + 1;
            end

            // Dequeue operation
            if (dequeue && !empty) begin
                data_out <= fifo[head];
                head <= (head + 1) % 4;
                count <= count - 1;
            end

            // Update empty and full flags
            empty <= (count == 0);
            full <= (count == 4);
        end
    end
endmodule

