module deserializer (
    input wire clk,
    input wire reset,
    input wire start,
    input wire serial_in,
    output reg [7:0] parallel_out,
    output reg data_valid
);
    reg [2:0] bit_count; // 3-bit counter for 8 bits
    reg receiving;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 3'b000;
            parallel_out <= 8'b00000000;
            data_valid <= 1'b0;
            receiving <= 1'b0;
        end else if (start && !receiving) begin
            receiving <= 1'b1;
            bit_count <= 3'b000;
            parallel_out <= 8'b00000000;
            data_valid <= 1'b0;
        end else if (receiving) begin
            if (bit_count < 3'b111) begin
                parallel_out[bit_count] <= serial_in;
                bit_count <= bit_count + 1;
            end else begin
                data_valid <= 1'b1;
                receiving <= 1'b0; // Stop receiving after 8 bits
            end
        end
    end
endmodule

module crc_generator (
    input clk,
    input reset,
    input start,
    input [31:0] data,
    input [31:0] polynomial,
    output reg [31:0] crc,
    output reg done
);
    reg [31:0] temp_data;
    reg [31:0] temp_crc;
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            crc <= 32'b0;
            done <= 0;
        end else if (start) begin
            temp_data <= data;
            temp_crc <= 32'b0;
            done <= 0;

            for (i = 0; i < 32; i = i + 1) begin
                if (temp_crc[31] ^ temp_data[31]) begin
                    temp_crc = (temp_crc << 1) ^ polynomial;
                end else begin
                    temp_crc = temp_crc << 1;
                end
                temp_data = temp_data << 1;
            end
            crc <= temp_crc;
            done <= 1;
        end
    end
endmodule

description:
Design a simple 8-bit ChaCha20 quarter round operation module. The module will take 8 input 8-bit values (a, b, c, d) and produce the corresponding 8 output values after performing the quarter round operation defined in the ChaCha20 algorithm. The operation is defined as follows:
1. a += b; d ^= a; d = (d << 16) | (d >> (32 - 16));
2. c += d; b ^= c; b = (b << 12) | (b >> (32 - 12));
3. a += b; d ^= a; d = (d << 8) | (d >> (32 - 8));
4. c += d; b ^= c; b = (b << 7) | (b >> (32 - 7));
The output will be the modified values of a, b, c, and d. The module should be triggered on a clock edge and resettable.

code:
module chacha20_quarter_round (
    input clk,
    input rst,
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output reg [7:0] out_a,
    output reg [7:0] out_b,
    output reg [7:0] out_c,
    output reg [7:0] out_d
);

reg [7:0] a_reg, b_reg, c_reg, d_reg;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        out_a <= 8'b0;
        out_b <= 8'b0;
        out_c <= 8'b0;
        out_d <= 8'b0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        c_reg <= c;
        d_reg <= d;

        // Quarter round operations
        a_reg <= a_reg + b_reg;
        d_reg <= d_reg ^ a_reg;
        d_reg <= {d_reg[15:0], d_reg[23:16]} ^ {d_reg[7:0], d_reg[31:24]}; // Rotate left 16

        c_reg <= c_reg + d_reg;
        b_reg <= b_reg ^ c_reg;
        b_reg <= {b_reg[11:0], b_reg[23:12]} ^ {b_reg[3:0], b_reg[31:24]}; // Rotate left 12

        a_reg <= a_reg + b_reg;
        d_reg <= d_reg ^ a_reg;
        d_reg <= {d_reg[7:0], d_reg[15:8]} ^ {d_reg[23:0], d_reg[31:24]}; // Rotate left 8

        c_reg <= c_reg + d_reg;
        b_reg <= b_reg ^ c_reg;
        b_reg <= {b_reg[6:0], b_reg[15:8]} ^ {b_reg[23:0], b_reg[31:24]}; // Rotate left 7

        out_a <= a_reg;
        out_b <= b_reg;
        out_c <= c_reg;
        out_d <= d_reg;
    end
end

endmodule

