module kalman_filter (
    input wire clk,
    input wire reset,
    input wire [15:0] z,           // Measurement value
    input wire [15:0] x_hat_prev,  // Previous estimate
    input wire [15:0] p_prev,      // Previous covariance
    output reg [15:0] x_hat,       // Updated estimate
    output reg [15:0] p            // Updated covariance
);
    reg [15:0] k; // Kalman Gain

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            x_hat <= 16'd0;
            p <= 16'd0;
        end else begin
            // Simple Kalman filter update equations
            k <= p_prev / (p_prev + 16'd1); // Assume measurement noise is 1
            x_hat <= x_hat_prev + k * (z - x_hat_prev);
            p <= (16'd1 - k) * p_prev;
        end
    end
endmodule

