module deserializer (  
    input wire clk,  
    input wire serial_in,  
    output reg [31:0] parallel_out  
);  
    reg [5:0] count; // 6 bits to count from 0 to 31  
    initial begin  
        count = 0;  
        parallel_out = 0;  
    end  
    always @(posedge clk) begin  
        if (count < 32) begin  
            parallel_out[count] <= serial_in;  
            count <= count + 1;  
        end else begin  
            count <= 0; // Reset count after 32 bits  
        end  
    end  
endmodule

