module round_robin_arbiter(  
    input wire clk,  
    input wire rst,  
    input wire [3:0] req,  
    output reg [3:0] grant  
);  
    reg [1:0] current;    

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            grant <= 4'b0000;  
            current <= 2'b00;  
        end  
        else begin  
            if (req) begin  
                grant <= 4'b0000;  
                // Check for the highest priority request based on current  
                case (current)  
                    2'b00: if (req[0]) grant[0] <= 1; else if (req[1]) grant[1] <= 1; else if (req[2]) grant[2] <= 1; else if (req[3]) grant[3] <= 1;  
                    2'b01: if (req[1]) grant[1] <= 1; else if (req[2]) grant[2] <= 1; else if (req[3]) grant[3] <= 1; else if (req[0]) grant[0] <= 1;  
                    2'b10: if (req[2]) grant[2] <= 1; else if (req[3]) grant[3] <= 1; else if (req[0]) grant[0] <= 1; else if (req[1]) grant[1] <= 1;  
                    2'b11: if (req[3]) grant[3] <= 1; else if (req[0]) grant[0] <= 1; else if (req[1]) grant[1] <= 1; else if (req[2]) grant[2] <= 1;  
                endcase  
                // Update current for next cycle  
                current <= current + 1;  
            end  
            else begin  
                grant <= 4'b0000;  
            end  
        end  
    end  
endmodule

