module chebyshev_filter (
    input [7:0] x, // 8-bit input signal
    output reg [7:0] y // 8-bit output signal
);
    // Coefficients for a simple 5th order Chebyshev filter
    parameter [7:0] a0 = 8'd1;
    parameter [7:0] a1 = 8'd5;
    parameter [7:0] a2 = 8'd10;
    parameter [7:0] a3 = 8'd10;
    parameter [7:0] a4 = 8'd5;
    parameter [7:0] a5 = 8'd1;

    reg [7:0] x_delay [0:4]; // delay elements for input signal

    always @(*) begin
        // Shift the delay elements
        x_delay[0] = x;
        x_delay[1] = x_delay[0];
        x_delay[2] = x_delay[1];
        x_delay[3] = x_delay[2];
        x_delay[4] = x_delay[3];

        // Calculate the output using the Chebyshev filter formula
        y = (a0 * x_delay[0] + a1 * x_delay[1] + a2 * x_delay[2] +
             a3 * x_delay[3] + a4 * x_delay[4]) >> 4; // shifting for normalization
    end
endmodule

module pipeline (
    input clk,
    input reset,
    input [4:0] instruction_in,
    output reg [4:0] instruction_out
);
    reg [4:0] IF_REG, ID_REG, EX_REG, MEM_REG;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            IF_REG <= 5'b00000;
            ID_REG <= 5'b00000;
            EX_REG <= 5'b00000;
            MEM_REG <= 5'b00000;
            instruction_out <= 5'b00000;
        end else begin
            IF_REG <= instruction_in;      // Stage 1: Instruction Fetch
            ID_REG <= IF_REG;              // Stage 2: Instruction Decode
            EX_REG <= ID_REG;              // Stage 3: Execute
            MEM_REG <= EX_REG;             // Stage 4: Memory Access
            instruction_out <= MEM_REG;    // Stage 5: Write Back
        end
    end
endmodule

