            direction = 8'h0F;
            write_data = 8'hF5;
            @(posedge clk);
            #2;

            #1;


            check_outputs(8'h05);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            reset_dut();
            $display("Test %0d: Alternating bit directions", test_num);
            direction = 8'hAA;
            write_data = 8'hFF;
            @(posedge clk);
            #2;

            #1;


            check_outputs(8'hAA);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            reset_dut();
            $display("Test %0d: Dynamic direction change", test_num);
            direction = 8'hFF;
            write_data = 8'hCC;
            @(posedge clk);
            #2;
            direction = 8'hF0;
            @(posedge clk);
            #2;

            #1;


